import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../core/widgets/states.dart';import '../providers/providers.dart';import '../widgets/content_cards.dart';
class TvScreen extends ConsumerStatefulWidget{final String?initialCategory;const TvScreen({super.key,this.initialCategory});@override ConsumerState<TvScreen>createState()=>_TvScreenState();}
class _TvScreenState extends ConsumerState<TvScreen>{final scroll=ScrollController();@override void initState(){super.initState();scroll.addListener(()=>scroll.position.pixels>scroll.position.maxScrollExtent-400?ref.read(channelsProvider.notifier).load():null);if(widget.initialCategory!=null)WidgetsBinding.instance.addPostFrameCallback((_)=>ref.read(channelsProvider.notifier).load(reset:true,categoryId:widget.initialCategory));}@override Widget build(BuildContext context){final s=ref.watch(channelsProvider);return Scaffold(appBar:AppBar(title:const Text('Telekanallar'),actions:[Padding(padding:const EdgeInsets.only(right:14),child:Center(child:Container(padding:const EdgeInsets.symmetric(horizontal:9,vertical:5),decoration:BoxDecoration(color:Colors.red,borderRadius:BorderRadius.circular(8)),child:const Text('● JONLI',style:TextStyle(fontSize:11,fontWeight:FontWeight.bold)))))]),body:RefreshIndicator(onRefresh:()=>ref.read(channelsProvider.notifier).load(reset:true),child:s.items.isEmpty&&s.loading?const AppLoading():s.error!=null&&s.items.isEmpty?AppErrorView(message:s.error!,onRetry:()=>ref.read(channelsProvider.notifier).load(reset:true)):GridView.builder(controller:scroll,padding:const EdgeInsets.fromLTRB(16,8,16,28),gridDelegate:const SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:210,mainAxisExtent:170,crossAxisSpacing:12,mainAxisSpacing:12),itemCount:s.items.length+(s.hasNext?1:0),itemBuilder:(_,i)=>i==s.items.length?const Center(child:CircularProgressIndicator()):ChannelCard(channel:s.items[i]))));}@override void dispose(){scroll.dispose();super.dispose();}}
